include "archeanrules.xc"
include "sidelogo.xc"
include "rtxon.xc"

var $window1 = screen (3,0)
var $window2 = screen (4,0)
var $screen = screen(0,0)
var $sprite = screen(0,0)
var $side1 = screen(1,0)
var $side2 = screen(2,0)
var $pccase = screen(5,0)
var $rtx = screen(11,0)
function @copyScreen()
;	screen_copy($sprites, $screen, $src_x, $src_y, $dst_x, $dst_y, $width, $height, $color)
	screen_copy($sprite, $screen, 0,0, 0,0, 400,400)

function @copyTiles($w:number,$h:number,$num:number)
	repeat $num ($x)
		repeat $num  ($y)
			screen_copy($sprite, $screen, 0,0, $x*$w,$y*$h, $w, $h)





init
	$sprite.blank()
	; @sprite_icon($sprite,x,y)
	print("sprite screen",$sprite.width,$sprite.height)
	print("main screen",$screen.width,$screen.height)

	@sprite_logo($sprite,0,10)
	@sprite_logoSIDE($side1,0,0)
	@sprite_logoSIDE($side2,0,0)
	@sprite_rtxOn($rtx,0,0)

	$window1.blank(color(0,0,0,200))
	$window2.blank(color(0,0,0,200))
	$pccase.blank(color(0,0,0,90))
	output_number(8, 0, 1)
	output_number(8, 1, 255)
